using System;using System.IO;public static class PackedBitmap {
public static void Decode(string source,string target){byte[] b=File.ReadAllBytes(source);int colors=b[1]+1,w=BitConverter.ToUInt16(b,2),h=BitConverter.ToUInt16(b,4),s=10+colors*3,d=0;byte[] data=new byte[w*h];data[d++]=b[s++];bool end=false;while(!end){int ctrl=unchecked((b[s++]<<24)+1);while(true){if(ctrl>=0){ctrl=unchecked(ctrl*2);data[d++]=b[s++];}else{int token=b[s++],count=token&15,back=((token&240)<<4)|b[s];if(count==0)count=-b[++s]-18;else count-=18;s++;if(back==0){end=true;break;}do{count++;data[d]=data[d-back];d++;}while(count!=0);ctrl=unchecked(ctrl*2);}if((ctrl&255)==0)break;}}using(var o=new BinaryWriter(File.Create(target))){o.Write((ushort)0x4d42);o.Write(54+w*h*3);o.Write(0);o.Write(54);o.Write(40);o.Write(w);o.Write(h);o.Write((ushort)1);o.Write((ushort)24);for(int i=0;i<6;i++)o.Write(0);for(int y=0;y<h;y++)for(int x=0;x<w;x++){int p=data[y*(w/2)+x/2];p=(x%2==0)?p>>4:p&15;for(int k=0;k<3;k++)o.Write(b[6+p*3+k]);}}}}